import java.util.*;

public final class Solution {
    public record Clip(String title, String url) {}

    public static List<Clip> decodeFeed(String payload) {
        if (payload == null) throw new IllegalArgumentException("payload");
        if (payload.isEmpty()) return List.of();
        if (payload.indexOf('\r') >= 0) throw new IllegalArgumentException("carriage return");
        String body = payload.endsWith("\n") ? payload.substring(0, payload.length() - 1) : payload;
        if (body.isEmpty()) throw new IllegalArgumentException("blank line");
        List<Clip> out = new ArrayList<>();
        for (String line : body.split("\n", -1)) {
            int p = line.indexOf('|');
            if (p <= 0 || p == line.length() - 1)
                throw new IllegalArgumentException("line");
            String title = line.substring(0, p), url = line.substring(p + 1);
            if (!title.equals(title.strip()) || !url.equals(url.strip())) throw new IllegalArgumentException("whitespace");
            out.add(new Clip(title, url));
        }
        return List.copyOf(out);
    }
}
